1	import 'dart:async';
2	
3	import 'package:flutter_bloc/flutter_bloc.dart';
4	
5	import '../../../../core/failure/failure.dart';
6	import '../../domain/entities/export_download_format.dart';
7	import '../../domain/entities/export_job_state.dart';
8	import '../../domain/repositories/export_repository.dart';
9	import '../../domain/services/download_opener.dart';
10	
11	/// Drives `ExportStatusSheet` (spec-7-1) — a fresh, `get_it`-factory-
12	/// scoped instance per download-icon tap (Code Map: the `registerFactory`
13	/// one-shot-cubit precedent set by `TextEntryCubit`), closed by the call
14	/// site itself once done with it (`MeusRegistrosScreen`'s own export handler/
15	/// `ExportStatusSheet.show()`, mirroring `InsertionModal.show()`'s own
16	/// cubit-disposal convention), never by a `get_it` `dispose:` hook.
17	///
18	/// Starts in [ExportJobState.preparing] — the same visual the
19	/// `export-summary-create` 202 response's own `status: 'pending'` always
20	/// implies (`openapi.yaml`), so no separate "creating..." state is needed
21	/// before [start]'s own `createJob` call resolves.
22	class ExportJobCubit extends Cubit<ExportJobState> {
23	  ExportJobCubit(this._repository, this._downloadOpener)
24	    : super(const ExportJobState.preparing());
25	
26	  final ExportRepository _repository;
27	  final DownloadOpener _downloadOpener;
28	
29	  /// Design Notes — fixed poll cadence (docs/input is silent on this):
30	  /// the server job always reaches a terminal state, so no client
31	  /// timeout exists either.
32	  static const _pollInterval = Duration(seconds: 2);
33	
34	  /// Review finding (blind-hunter/edge-case-hunter layers) — a persistent
35	  /// `getStatus` failure (as opposed to one flaky blip) would otherwise
36	  /// poll forever with the sheet stuck on its last state and no visible
37	  /// indication anything is wrong. After this many *consecutive* failures,
38	  /// [_poll] gives up and surfaces the existing generic [ExportJobError]
39	  /// state instead — reusing the sheet's own already-built error visual
40	  /// rather than inventing a new one.
41	  static const _maxConsecutivePollFailures = 5;
42	
43	  String? _jobId;
44	  Timer? _pollTimer;
45	  int _consecutivePollFailures = 0;
46	
47	  /// Review finding (blind-hunter/edge-case-hunter layers) — `Timer.
48	  /// periodic` doesn't wait for one tick's own `_poll()` to finish before
49	  /// firing the next; without this guard, a `getStatus` call slower than
50	  /// [_pollInterval] could race a second, overlapping call, and a late,
51	  /// stale response landing after a newer terminal state was already
52	  /// emitted could "un-terminate" an already-finished job in the UI.
53	  bool _pollInFlight = false;
54	
55	  /// Creates the export job for [periodStart]/[periodEnd]
56	  /// (`export-summary-create`) and, on success, starts this cubit's own
57	  /// `Timer.periodic` poll loop against `export-status-get`.
58	  ///
59	  /// Returns `false` on a create failure (Boundaries: "Create fails →
60	  /// inline error, sheet never opens") — the same failure is also
61	  /// emitted as [ExportJobState.error] so the caller can read [state] for
62	  /// [Failure.message] without this method also having to hand back the
63	  /// raw `Failure` itself (the `Either<Failure, T>` shape, RNF09, is the
64	  /// repository's own contract, not every cubit method's). spec-7-3's one
65	  /// exception: an [ExportEmptyPeriod] create failure returns `true` and
66	  /// emits [ExportJobState.emptyPeriod] instead — the backend rejects a
67	  /// zero-Entry period synchronously, before a `jobId` ever exists, so
68	  /// the sheet opens directly on "Período vazio" with no job underneath.
69	  Future<bool> start({
70	    required DateTime periodStart,
71	    required DateTime periodEnd,
72	  }) async {
73	    final result = await _repository.createJob(
74	      periodStart: periodStart,
75	      periodEnd: periodEnd,
76	    );
77	    if (isClosed) {
78	      return false;
79	    }
80	    return result.match(
81	      (failure) {
82	        // spec-7-3: `export-summary-create` rejects a zero-Entry period
83	        // synchronously (400, non-retryable, never issues a `jobId`) —
84	        // distinct from `_poll`'s own `EXPORT_EMPTY_PERIOD` handling
85	        // (which starts from an already-issued `jobId`). Special-cased
86	        // here via an `is` check on the existing `ExportEmptyPeriod`
87	        // (AD-3) rather than a new `Failure` subtype or a string check.
88	        if (failure is ExportEmptyPeriod) {
89	          emit(const ExportJobState.emptyPeriod());
90	          return true;
91	        }
92	        emit(ExportJobState.error(failure));
93	        return false;
94	      },
95	      (jobId) {
96	        _jobId = jobId;
97	        _startPolling();
98	        return true;
99	      },
100	    );
101	  }
102	
103	  void _startPolling() {
104	    _pollTimer?.cancel();
105	    _pollTimer = Timer.periodic(_pollInterval, (_) => _poll());
106	  }
107	
108	  Future<void> _poll() async {
109	    final jobId = _jobId;
110	    if (jobId == null || _pollInFlight || _isTerminal(state)) {
111	      return;
112	    }
113	    _pollInFlight = true;
114	    try {
115	      final result = await _repository.getStatus(jobId);
116	      if (isClosed || _isTerminal(state)) {
117	        return;
118	      }
119	      result.match(
120	        (failure) {
121	          // A transient poll failure (docs/input is silent on this) is
122	          // swallowed rather than surfaced, so one flaky network blip
123	          // never flips a still-running job to a false terminal error —
124	          // the next tick simply tries again. A *persistent* one gives up
125	          // after [_maxConsecutivePollFailures] instead of polling
126	          // forever.
127	          _consecutivePollFailures++;
128	          if (_consecutivePollFailures >= _maxConsecutivePollFailures) {
129	            _pollTimer?.cancel();
130	            emit(ExportJobState.error(failure));
131	          }
132	        },
133	        (newState) {
134	          _consecutivePollFailures = 0;
135	          emit(newState);
136	          if (_isTerminal(newState)) {
137	            _pollTimer?.cancel();
138	          }
139	        },
140	      );
141	    } finally {
142	      _pollInFlight = false;
143	    }
144	  }
145	
146	  bool _isTerminal(ExportJobState state) =>
147	      state is ExportJobDone ||
148	      state is ExportJobError ||
149	      state is ExportJobEmptyPeriod;
150	
151	  /// Review finding (code review, patch item 3), keyed by [format] —
152	  /// mirrors [_pollInFlight]: without this guard, a rapid double-tap on
153	  /// the *same* download button could fire two overlapping [_download]
154	  /// calls for it, each with its own `getDownloadUrl`/`DownloadOpener.open`
155	  /// pair in flight at once. Keyed per-format (review finding, round 2 —
156	  /// a single shared flag silently dropped a legitimate, concurrent tap on
157	  /// the *other* format's button while the first was still in flight,
158	  /// since both "Baixar PDF"/"Baixar dados brutos" can be enabled at the
159	  /// same time in the `narrativeReady` outcome) so the two formats never
160	  /// block each other. A second call for an already-in-flight format is a
161	  /// no-op — resolves to `null` (no failure to surface) without touching
162	  /// the repository or the opener at all.
163	  final Set<ExportDownloadFormat> _downloadsInFlight = {};
164	
165	  static const _downloadFailureMessage = 'Não foi possível abrir o arquivo.';
166	
167	  /// "Baixar PDF" — see [_download].
168	  Future<Failure?> downloadPdf() => _download(ExportDownloadFormat.pdf);
169	
170	  /// "Baixar dados brutos" — see [_download].
171	  Future<Failure?> downloadRawData() => _download(ExportDownloadFormat.raw);
172	
173	  /// Resolves [format]'s signed download URL (`export-download-get`) and
174	  /// hands it to [_downloadOpener] to open externally — never buffered in
175	  /// this app (Boundaries). Returns `null` on success, or the `Failure`
176	  /// that explains why otherwise — `ExportStatusSheet._handleDownload`
177	  /// awaits this return value directly, rather than reading it back off a
178	  /// side-channel field (review finding: a shared mutable field, written
179	  /// by the cubit and mutated by the widget, broke encapsulation and was
180	  /// racy before [_downloadsInFlight] existed).
181	  Future<Failure?> _download(ExportDownloadFormat format) async {
182	    if (_downloadsInFlight.contains(format)) {
183	      return null;
184	    }
185	    _downloadsInFlight.add(format);
186	    try {
187	      final jobId = _jobId;
188	      if (jobId == null) {
189	        // Shouldn't happen — every download button only ever renders once
190	        // `start()` has already stored a jobId — but silently reporting
191	        // success here would be indistinguishable from a real one
192	        // (review finding, patch item 4).
193	        return const Failure.malformedResponse(
194	          message: _downloadFailureMessage,
195	        );
196	      }
197	      final result = await _repository.getDownloadUrl(jobId, format: format);
198	      // Review finding (round 2) — [_downloadOpener.open] is a pure
199	      // side-effect handoff to the OS; it never touches [state]/[emit], so
200	      // there's no encapsulation reason to skip it once [isClosed] (unlike
201	      // [_poll]'s own `isClosed` guard, which exists specifically to avoid
202	      // emitting after disposal). Short-circuiting here used to silently
203	      // drop the user's download the instant they dismissed the sheet.
204	      return await result.match((failure) async => failure, (url) async {
205	        try {
206	          final opened = await _downloadOpener.open(url);
207	          return opened
208	              ? null
209	              : const Failure.malformedResponse(
210	                  message: _downloadFailureMessage,
211	                );
212	        } catch (_) {
213	          // [DownloadOpener]'s own contract never promises it won't throw
214	          // — the real `UrlLauncherDownloadOpener` already catches
215	          // internally, but nothing enforces that on the port itself
216	          // (review finding, patch item 5). RNF09: never let a thrown
217	          // exception escape uncaught out of `_handleDownload`'s own
218	          // unguarded `await`.
219	          return const Failure.malformedResponse(
220	            message: _downloadFailureMessage,
221	          );
222	        }
223	      });
224	    } finally {
225	      _downloadsInFlight.remove(format);
226	    }
227	  }
228	
229	  @override
230	  Future<void> close() {
231	    _pollTimer?.cancel();
232	    return super.close();
233	  }
234	}
