32	/// newest-first, grouped by day, each card marked by origin. Replaces the
33	/// former `MeusRegistrosPlaceholderScreen`.
34	///
35	/// [cubit] is a DI `lazySingleton` (Code Map) — this `StatefulWidget` never
36	/// closes it (`BlocProvider.value`, same convention
37	/// `AccountSettingsScreen` already uses for its own singleton cubit); only
38	/// this screen's own [ScrollController] is this `State`'s to dispose.
39	///
40	/// The global `ExpiryOverlayHost` shows its "Sessão expirada" dialog via
41	/// `showGeneralDialog` on the `Navigator` *above* this screen's own widget
42	/// subtree (`expiry_overlay_host.dart`) — this screen is never popped or
43	/// rebuilt from scratch underneath it, so [_scrollController]'s position
44	/// and [cubit]'s state survive that overlay appearing with no extra code
45	/// needed here (Acceptance Criteria's third bullet).
46	class MeusRegistrosScreen extends StatefulWidget {
47	  const MeusRegistrosScreen({
48	    required this.cubit,
49	    required this.searchCubit,
50	    super.key,
51	  });
52	
53	  final MeusRegistrosCubit cubit;
54	
55	  /// spec-5-1 — the permanently-docked `EntriesSearchBar`'s own cubit, a DI
56	  /// `lazySingleton` like [cubit] (Code Map); this `StatefulWidget` never
57	  /// closes it either, same rationale [cubit]'s own doc above gives.
58	  final EntriesSearchCubit searchCubit;
59	
60	  @override
61	  State<MeusRegistrosScreen> createState() => _MeusRegistrosScreenState();
62	}
