247	  void _onScroll() {
248	    if (!_scrollController.hasClients) {
249	      return;
250	    }
251	    final position = _scrollController.position;
252	    // Pre-fetches a little before the exact end (reusing `spacing2xl`
253	    // purely as a scroll-distance buffer, not a new literal) for a
254	    // smoother scroll-pagination feel; `loadMore()` itself is a no-op once
255	    // there's no further page or a call is already in flight.
256	    if (position.pixels >= position.maxScrollExtent - DesignTokens.spacing2xl) {
257	      widget.cubit.loadMore();
258	    }
259	  }
